SELECT p.id AS position_id, c.id, c.interval_code, c.open_time, c.close_time, c.open_price, c.high_price, c.low_price, c.close_price, c.volume, c.number_of_trades, c.taker_buy_base_volume, c.closed, c.created_at, TIMESTAMPDIFF(MICROSECOND, c.close_time, c.created_at)/1000000 AS created_lag_s FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id JOIN candle c ON c.symbol=p.symbol AND c.interval_code='1m' AND c.open_time BETWEEN s.candle_open_time - INTERVAL 5 MINUTE AND s.candle_open_time WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, c.open_time LIMIT 60;
SELECT COLUMN_NAME, DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='crypto_ai' AND TABLE_NAME='candle' ORDER BY ORDINAL_POSITION